PAYLOAD = b"KeelShell fixed archive stream probe.\n"
MEMBER = "keelshell-probe.txt"
MAX_PATH = 4096
MAX_VERSION = 256
MAX_RESPONSE = 32768
COMMAND_OUTPUT = 4096
TOTAL_OUTPUT = 16384
COMMAND_SECONDS = 1.0
TOTAL_SECONDS = 6.0
CLEANUP_SECONDS = 0.2
STOPPED = False

# The child source is fully visible in the review command. Both formats stay in BytesIO.
PYTHON_STREAM = """import sys
